open(p+'.py','w').write('''def transform(grid):
    H, W = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(c for r in grid for c in r)
    fill = cnt.most_common(1)[0][0]
    line = cnt.most_common(2)[1][0]
    marks = {}
    for i, r in enumerate(grid):
        for j, c in enumerate(r):
            if c not in (fill, line):
                marks.setdefault(c, []).append((i, j))
    ok = {line} | set(marks)
    hl = [i for i in range(H) if all(c in ok for c in grid[i])]
    vl = [j for j in range(W) if all(grid[i][j] in ok for i in range(H))]
    rects = []
    for c, pts in marks.items():
        cells = {(hl.index(i), vl.index(j)) for i, j in pts}
        rows = sorted({r for r, _ in cells})
        groups = []; cur = []; prev = None; pcs = None
        for r in rows:
            cs = frozenset(j for i, j in cells if i == r)
            if prev is not None and r == prev + 1 and cs == pcs:
                cur.append(r)
            else:
                if cur: groups.append((cur, pcs))
                cur = [r]
            prev = r; pcs = cs
        if cur: groups.append((cur, pcs))
        for rs, cs in groups:
            rects.append((c, min(rs), max(rs), min(cs), max(cs)))
    blocks = [(c, r1, r2 - 1, c1, c2 - 1) for c, r1, r2, c1, c2 in rects]
    rws = [r for _, a, b, _, _ in blocks for r in (a, b)]
    cls = [c for _, _, _, x, y in blocks for c in (x, y)]
    r0, r1b, c0, c1b = min(rws), max(rws), min(cls), max(cls)
    out = [[fill] * (c1b - c0 + 1) for _ in range(r1b - r0 + 1)]
    for c, a, b, x, y in blocks:
        for i in range(a, b + 1):
            for j in range(x, y + 1):
                out[i - r0][j - c0] = c
    return out
''')
